const fs = require('fs');

function input_split() {
    const buf = fs.readFileSync(0, 'utf8');
    return buf.trim()
        .split(/\s+/)
        .map(elem => parseInt(elem, 10));
}

function determine_b(v) {
    const sum = v.reduce((acc, x) => acc + x, 0);
    if (sum % 5 === 0 && sum !== 0) {
        return sum / 5;
    } else {
        return null;
    }
}

function print(res) {
    if (res !== null) {
        process.stdout.write(String(res));
    } else {
        process.stdout.write("-1");
    }
}

function main() {
    print(determine_b(input_split()));
}

main();

